data.minimal_example:
dependencies:
  unified_popups: ^2.2.3

MaterialApp(
  navigatorObservers: [Pop.routeObserver],
  builder: Pop.hostBuilder,
  home: const HomePage(),
);

Pop.toast(const ToastConfig.text('Saved', type: ToastType.success));

final ok = await Pop.confirm(const ConfirmConfig(
  title: 'Delete?',
  content: 'This cannot be undone.',
  confirmText: 'Delete',
  cancelText: 'Cancel',
)).result;
